export interface ManuscriptDoor {
  id: string;
  title: string;
  paragraphs: string[];
}

export interface SpecialSection {
  title: string;
  paragraphs: string[];
}

const epilogueParagraphs: string[] = [];
manuscriptData.epilogue.sections.forEach((sec) => {
  epilogueParagraphs.push(sec.heading);
  epilogueParagraphs.push(...sec.paragraphs);
});
epilogueParagraphs.push(manuscriptData.epilogue.closingSignature.recipient);
epilogueParagraphs.push(...manuscriptData.epilogue.closingSignature.honorifics);
epilogueParagraphs.push(...manuscriptData.epilogue.closingSignature.closingCharter);
epilogueParagraphs.push(manuscriptData.epilogue.closingSignature.signOff);
epilogueParagraphs.push(manuscriptData.epilogue.closingSignature.author);
epilogueParagraphs.push(manuscriptData.epilogue.closingSignature.date);

export const SPECIAL_SECTIONS: Record<string, SpecialSection> = {
  cover: {
    title: "الغلاف الداخلي",
    paragraphs: manuscriptData.cover.requestText,
  },
  covenant: {
    title: manuscriptData.charter.title,
    paragraphs: manuscriptData.charter.text,
  },
  dedication: {
    title: manuscriptData.dedication.title,
    paragraphs: manuscriptData.dedication.text,
  },
  introMain: {
    title: manuscriptData.introduction.title,
    paragraphs: manuscriptData.introduction.preamble,
  },
  conclusion: {
    title: manuscriptData.epilogue.title,
    paragraphs: epilogueParagraphs,
  },
};

export const MANUSCRIPT_DOORS: Record<string, ManuscriptDoor> = {};

// Populate introduction sections
manuscriptData.introduction.sections.forEach((sec, idx) => {
  const door: ManuscriptDoor = {
    id: sec.id,
    title: sec.title,
    paragraphs: sec.content,
  };
  MANUSCRIPT_DOORS[sec.id] = door;
  MANUSCRIPT_DOORS[`intro-door-${idx + 1}`] = door;
});

// Populate chapters sections
manuscriptData.chapters.forEach((ch, chIdx) => {
  const chNum = chIdx + 1;
  ch.sections.forEach((sec, sIdx) => {
    const doorNumber = sIdx + 1;
    const door: ManuscriptDoor = {
      id: sec.id,
      title: sec.subtitle ? `${sec.title} — ${sec.subtitle}` : sec.title,
      paragraphs: sec.content,
    };
    MANUSCRIPT_DOORS[sec.id] = door;
    MANUSCRIPT_DOORS[`ch${chNum}-door-${doorNumber}`] = door;
    MANUSCRIPT_DOORS[`ch${ch.number}-door-${doorNumber}`] = door;
  });
});